/**
 * Small Mermaid flowchart writer shared by the Compose and Kubernetes diagram builders.
 * Node ids are generated by the caller (letters, digits, underscore); every label is escaped here.
 */

export type FlowShape = 'rect' | 'round' | 'stadium' | 'cylinder' | 'hexagon' | 'parallelogram' | 'asym' | 'circle';

export interface FlowNode {
  id: string;
  /** Label lines, plain text. Joined with a line break. */
  lines: string[];
  shape?: FlowShape;
  classes?: string[];
  /** Id of the subgraph this node sits in. */
  group?: string;
}

export interface FlowGroup { id: string; label: string }

export interface FlowEdge {
  from: string;
  to: string;
  label?: string;
  dotted?: boolean;
  /** No arrow head. */
  plain?: boolean;
  /** Drawn in red (dependency cycle, broken link). */
  problem?: boolean;
}

export interface FlowChart {
  direction: 'LR' | 'TB';
  nodes: FlowNode[];
  groups?: FlowGroup[];
  edges: FlowEdge[];
  classDefs?: Record<string, string>;
}

export interface FlowResult {
  text: string;
  nodes: number;
  edges: number;
  /** Nodes or edges were left out because of the cap. */
  truncated: boolean;
}

export const DIAGRAM_CAP = 300;
const MAX_LABEL = 80;

/**
 * Makes text safe inside a quoted Mermaid label: characters with a meaning to the parser
 * (quotes, #, %, ;, |, <, >, &, backtick) become Mermaid entity codes, line breaks become spaces.
 */
export function mermaidText(raw: unknown, max = MAX_LABEL): string {
  let s = String(raw ?? '').replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim();
  if (s.length > max) s = s.slice(0, max - 1) + '…';
  return s.replace(/[#&"<>`%;|\\{}[\]]/g, ch => `#${ch.charCodeAt(0)};`);
}

const OPEN: Record<FlowShape, [string, string]> = {
  rect: ['[', ']'], round: ['(', ')'], stadium: ['([', '])'], cylinder: ['[(', ')]'],
  hexagon: ['{{', '}}'], parallelogram: ['[/', '/]'], asym: ['>', ']'], circle: ['((', '))'],
};

function nodeLine(n: FlowNode): string {
  const [a, b] = OPEN[n.shape ?? 'rect'];
  const label = n.lines.filter(l => l !== '').map(l => mermaidText(l)).join('<br/>') || ' ';
  const cls = n.classes?.length ? `:::${n.classes[0]}` : '';
  return `${n.id}${a}"${label}"${b}${cls}`;
}

function edgeLine(e: FlowEdge): string {
  const arrow = e.dotted ? (e.plain ? '-.-' : '-.->') : (e.plain ? '---' : '-->');
  const label = e.label ? `|"${mermaidText(e.label)}"|` : '';
  return `${e.from} ${arrow}${label} ${e.to}`;
}

/** Writes the chart. Keeps at most `cap` nodes and `cap` edges, in the order given. */
export function renderFlowchart(chart: FlowChart, cap = DIAGRAM_CAP): FlowResult {
  const nodes = chart.nodes.slice(0, cap);
  const groups = chart.groups ?? [];
  const nodeIds = new Set(nodes.map(n => n.id));
  const known = new Set(groups.map(g => g.id));
  const usedGroups = new Set(nodes.map(n => n.group).filter((g): g is string => !!g && known.has(g)));
  const ends = new Set([...nodeIds, ...[...usedGroups]]);
  const valid = chart.edges.filter(e => ends.has(e.from) && ends.has(e.to));
  const edges = valid.slice(0, cap);
  const truncated = chart.nodes.length > nodes.length || valid.length > edges.length;

  const out: string[] = [`flowchart ${chart.direction}`];
  for (const g of groups) {
    if (!usedGroups.has(g.id)) continue;
    out.push(`  subgraph ${g.id}["${mermaidText(g.label)}"]`);
    for (const n of nodes) if (n.group === g.id) out.push(`    ${nodeLine(n)}`);
    out.push('  end');
  }
  for (const n of nodes) if (!n.group || !known.has(n.group)) out.push(`  ${nodeLine(n)}`);
  for (const e of edges) out.push(`  ${edgeLine(e)}`);
  const red = edges.map((e, i) => (e.problem ? i : -1)).filter(i => i >= 0);
  if (red.length) out.push(`  linkStyle ${red.join(',')} stroke:#dc2626,stroke-width:2px`);
  for (const [name, style] of Object.entries(chart.classDefs ?? {})) out.push(`  classDef ${name} ${style}`);
  return { text: out.join('\n'), nodes: nodes.length, edges: edges.length, truncated };
}
